mapper.select:
SELECT ru.id, ru.user_id, u.username, ru.mobile, ru.admin_flag, u.status, ru.real_name, ru.org_id FROM sys_rs_user_info ru inner JOIN sys_rs_user u ON ru.user_id = u.id and u.deleted=0 WHERE ru.deleted = 0 AND u.user_type = 1
AND ru.mobile = #{mobile}
AND u.status = #{status}
ORDER BY u.create_time DESC
